window.SEARCH_INDEX = [{"url":"problems/2567-minimum-score-by-changing-two-elements.html","title":"2567. Minimum Score by Changing Two Elements","zh":"修改兩個元素的最小分數","level":"Medium","series":"每日一題","date":"2026-11-19","nums":[2567],"tags":["排序","貪心"],"desc":"low 一定能變成 0（把改掉的數改成跟別人一樣），所以只剩 high = 最大 − 最小。排序後只有三種改法：改最小的兩個、改最大的兩個、左右各改一個，三者取最小。進階不用排序：一次走訪記下前三小和前三大，O(n) 時間、O(1) 空間。","cover":"assets/img/2567-minimum-score-by-changing-two-elements.jpg"},{"url":"problems/2914-minimum-number-of-changes-to-make-binary-string-beautiful.html","title":"2914. Minimum Number of Changes to Make Binary String Beautiful","zh":"使二進位字串變美麗的最少修改次數","level":"Medium","series":"每日一題","date":"2026-11-18","nums":[2914],"tags":["字串","貪心"],"desc":"關鍵觀察：每一段長度都是偶數，所以切點一定在偶數位置，任何美麗字串都能拆成 (0,1)、(2,3)… 一對一對、每對兩個字元相同。於是只要兩兩一組檢查，不同就改一次，O(n) 時間、O(1) 空間。","cover":"assets/img/2914-minimum-number-of-changes-to-make-binary-string-beautiful.jpg"},{"url":"problems/2911-minimum-changes-to-make-k-semi-palindromes.html","title":"2911. Minimum Changes to Make K Semi-palindromes","zh":"得到 K 個半回文串的最少修改次數","level":"Hard","series":"每日一題","date":"2026-11-17","nums":[2911],"tags":["動態規劃","字串","因數"],"desc":"分三步：先懂半回文（選一個比長度小的因數 d，按 i mod d 分組，每組各自是回文）；再用因數表算出每一段的代價 cost[l][r]，取所有 d 裡最少的修改次數；最後切段 DP：dp[i][j] = 前 i 個字元切成 j 段的最小代價，枚舉最後一段的起點轉移。","cover":"assets/img/2911-minimum-changes-to-make-k-semi-palindromes.jpg"},{"url":"problems/2243-calculate-digit-sum-of-a-string.html","title":"2243. Calculate Digit Sum of a String","zh":"計算字串的數字和","level":"Easy","series":"每日一題","date":"2026-11-16","nums":[2243],"tags":["字串","模擬"],"desc":"照規則模擬：長度大於 k 就做一輪，每 k 個字元分一組（最後一組可以不滿 k 個），把每組的數字加總，再把總和轉回字串接起來，直到長度不超過 k。重點是字元轉數字 s[j] − '0'，以及數字轉字串 to_string。","cover":"assets/img/2243-calculate-digit-sum-of-a-string.jpg"},{"url":"problems/1524-number-of-sub-arrays-with-odd-sum.html","title":"1524. Number of Sub-arrays With Odd Sum","zh":"和為奇數的子陣列數目","level":"Medium","series":"每日一題","date":"2026-11-15","nums":[1524],"tags":["前綴和","數學","計數"],"desc":"子陣列總和 = 兩個前綴和相減，相減是奇數 ⇔ 兩個前綴和一奇一偶。從左掃到右，只記前綴和的奇偶，以及前面出現過幾個奇數、幾個偶數（P[0] = 0 算一個偶數），現在是奇數就加上偶數的個數、反之亦然。O(n) 時間、O(1) 空間，答案記得取餘數。","cover":"assets/img/1524-number-of-sub-arrays-with-odd-sum.jpg"},{"url":"problems/3364-minimum-positive-sum-subarray.html","title":"3364. Minimum Positive Sum Subarray","zh":"最小正和子陣列","level":"Easy","series":"每日一題","date":"2026-11-14","nums":[3364],"tags":["陣列","枚舉"],"desc":"練習怎麼枚舉所有子陣列：固定起點 i，往右延伸到 j，總和只要加上新的一個數。長度在 [l, r] 之間而且總和大於 0 就更新答案，找不到回傳 −1。n 最多 100，O(n²) 就夠了。","cover":"assets/img/3364-minimum-positive-sum-subarray.jpg"},{"url":"problems/3420-count-non-decreasing-subarrays.html","title":"3420. Count Non-Decreasing Subarrays After K Operations","zh":"操作後的非遞減子陣列數量","level":"Hard","series":"每日一題","date":"2026-11-13","nums":[3420],"tags":["滑動視窗","單調佇列"],"desc":"一段子陣列的花費 = 每個數墊到前綴最大值要加多少。花費有兩個單調性，所以由右往左移動左端點、用滑動視窗收右端；單調雙端佇列把「補到的高度」分塊存成（高度, 個數），加入和移除都是均攤 O(1)，總共 O(n)，記得用 long long。","cover":"assets/img/3420-count-non-decreasing-subarrays.jpg"},{"url":"problems/3105-longest-monotonic-subarray.html","title":"3105. Longest Strictly Increasing or Strictly Decreasing Subarray","zh":"最長的嚴格遞增或遞減子陣列","level":"Easy","series":"每日一題","date":"2026-11-12","nums":[3105],"tags":["陣列","一次掃描"],"desc":"從左到右掃一次，同時記住「以 i 結尾」的遞增長度 inc 和遞減長度 dec：比前一個大就 inc++、dec 歸 1；比前一個小就反過來；相等就兩個都歸 1。答案是一路上的最大值，至少是 1。","cover":"assets/img/3105-longest-monotonic-subarray.jpg"},{"url":"problems/3789-minimum-cost-to-acquire-required-items.html","title":"3789. Minimum Cost to Acquire Required Items","zh":"取得所需物品的最小花費","level":"Medium","series":"每日一題","date":"2026-11-11","nums":[3789],"tags":["數學","貪心"],"desc":"枚舉套餐數量 x，總花費 f(x) 是先降後升的折線，最低點只會在 0、min(need)、max(need) 三個轉折點。換成貪心：配對的部分取 min(costBoth, cost1 + cost2)，單邊剩下的取 min(cost, costBoth)，記得用 long long。","cover":"assets/img/3789-minimum-cost-to-acquire-required-items.jpg"},{"url":"problems/dp04-counting-stairs.html","title":"DP 刷題單 #4 · 計數型爬樓梯","zh":"2466 · 91","level":"Medium","series":"動態規劃刷題單","date":"2026-11-10","nums":[2466,91],"tags":["動態規劃","計數"],"desc":"2466：把字串長度看成樓梯階數，每步爬 zero 或 one 階，dp[i] = dp[i − zero] + dp[i − one]，記得每一步都取餘數。91：每一步先檢查條件，單獨一個數字不能是 0、兩個數字要在 10 到 26 之間，才能從前一階或前兩階走過來。","cover":"assets/img/dp04-counting-stairs.jpg"},{"url":"problems/3693-climbing-stairs-ii.html","title":"3693. Climbing Stairs II","zh":"爬樓梯 II","level":"Medium","series":"每日一題","date":"2026-11-10","nums":[3693],"tags":["動態規劃"],"desc":"每次可以跳 1、2、3 階，從 i 跳到 j 要付 costs[j] + (j − i)²。貪心只看眼前會出錯，改用 dp[j] = min(dp[j−k] + costs[j] + k²)，最後再用三個變數把空間壓到 O(1)。","cover":"assets/img/3693-climbing-stairs-ii.jpg"},{"url":"problems/dp03-delete-and-earn.html","title":"DP 刷題單 #3 · 740. Delete and Earn","zh":"刪除並獲得點數","level":"Medium","series":"動態規劃刷題單","date":"2026-11-10","nums":[740],"tags":["動態規劃"],"desc":"拿了一個 x，剩下的 x 也應該全部拿走，所以決定的單位是「哪一種數字」。把相同數字的點數裝進桶子 sum[v]，相鄰的桶子不能同時選，就變成對桶子陣列跑一次打家劫舍。","cover":"assets/img/dp03-delete-and-earn.jpg"},{"url":"problems/dp02-house-robber-i-ii.html","title":"DP 刷題單 #2 · 打家劫舍 I & II","zh":"198 · 213","level":"Medium","series":"動態規劃刷題單","date":"2026-11-09","nums":[198,213],"tags":["動態規劃"],"desc":"198：先看兩種貪心為什麼錯，再定義 dp[i] = 前 i 間房子能偷到的最多錢，偷或不偷取較大值。213：房子圍成一圈，拆成「不偷最後一間」和「不偷第一間」兩條直線，各跑一次 198 再取較大值。","cover":"assets/img/dp02-house-robber-i-ii.jpg"},{"url":"problems/1606-find-servers-that-handled-most-requests.html","title":"1606. Find Servers That Handled Most Number of Requests","zh":"找到處理最多請求的伺服器","level":"Hard","series":"每日一題","date":"2026-11-09","nums":[1606],"tags":["有序集合","優先佇列"],"desc":"忙碌的伺服器放進按結束時間排序的堆積，空閒的伺服器放進有序集合，用 lower_bound 找「從 i % k 開始往後第一台」空閒伺服器，找不到就繞回開頭。","cover":"assets/img/1606-find-servers-that-handled-most-requests.jpg"},{"url":"problems/dp01-intro.html","title":"DP 刷題單 #1 · 入門","zh":"509 · 1137 · 70 · 746","level":"Easy","series":"動態規劃刷題單","date":"2026-11-08","nums":[509,1137,70,746],"tags":["動態規劃","記憶化"],"desc":"從費氏數列認識動態規劃：遞迴 → 記憶化 → 由下而上填表 → 滾動變數。再用同一套想法解泰波那契、爬樓梯和最小花費爬樓梯。","cover":"assets/img/dp01-intro.jpg"},{"url":"problems/1267-count-servers-that-communicate.html","title":"1267. Count Servers that Communicate","zh":"統計參與通信的伺服器","level":"Medium","series":"每日一題","date":"2026-11-08","nums":[1267],"tags":["計數","矩陣"],"desc":"先數每一列、每一行各有幾台伺服器；一台伺服器只要所在的列或行超過一台，就能通訊。也介紹看成圖、DFS、並查集的另解。","cover":"assets/img/1267-count-servers-that-communicate.jpg"},{"url":"problems/1882-process-tasks-using-servers.html","title":"1882. Process Tasks Using Servers","zh":"使用伺服器處理任務","level":"Medium","series":"每日一題","date":"2026-11-07","nums":[1882],"tags":["優先佇列","模擬"],"desc":"用兩個堆積模擬：空閒伺服器按（權重, 編號）排，忙碌伺服器按空閒時間排。所有伺服器都在忙時，時間直接跳到最早空出來的那一刻。","cover":"assets/img/1882-process-tasks-using-servers.jpg"},{"url":"problems/0042-trapping-rain-water.html","title":"42. Trapping Rain Water","zh":"接雨水","level":"Hard","series":"經典題","date":"2026-11-07","nums":[42],"tags":["雙指針","單調棧","前綴最大值"],"desc":"每一格能裝的水 = 左右最高牆的較小值 − 自己的高度。從暴力法一路優化到雙指針 O(n)、O(1) 空間，再用單調棧換個角度一層一層算。","cover":"assets/img/0042-trapping-rain-water.jpg"}];
